const raw = $input.item.json.text.replace(/```json|```/g,'').trim();
const post = JSON.parse(raw);
const fullText = post.post_text + '\n\n' + post.hashtags.map(h=>'#'+h).join(' ');
return [{ json: { ...post, full_post: fullText, notion_page_id: $('Fetch Approved Content').item.json.id } }];
